func unfix(str string) string {
	type kv struct{ k, v string }
	var vars []kv
	for _, s := range []string{
		"uname.os",
		"target.abi", "target.arch", "target.os", "target.release", "target.vendor",
		"variant.tag", "variant.target",
		"toolchain.resourceDir", "toolchain", "platforms", "sysroot",
		"modules", "testdata", "workspace", "workout", "workext",
		"PATH", "user",
	}{
		if v, ok := variables[s]; ok {
			vars = append(vars, kv{v.(string),`%[`+s+`]`})
		}
	}
	vars = append(vars,
		kv{getUname(0),`%[uname.0]`},
		kv{getUname(1),`%[uname.1]`},
		kv{getUname(2),`%[uname.2]`},
		kv{getUname(3),`%[uname.3]`},
	)
	for _, t := range vars { str = strings.ReplaceAll(str, t.k, t.v) }
	return strings.ReplaceAll(str, "\n", `\n`)
}

func fixCheckpoint(s string) string {
	return rxCheckReplacements.ReplaceAllStringFunc(s, func(match string) string {
		sm := rxCheckReplacements.FindStringSubmatch(match)
		if len(sm) < 7 { // Adjusted length due to unified prefix capture group
			return match
		}

		preChain := sm[1] // e.g., "dir+trim(/)"
		midStr := sm[2]   // variable name
		midIdx := sm[3]   // .[idx] on the variable
		sufAct := sm[4]   // suffix action + args
		sufArg := sm[5]   // inner arg
		sufAdd := sm[6]   // +1 -1

		a, exists := variables[midStr]
		if !exists {
			return match
		}

		var val string
		var vals []string
		switch t := a.(type) {
		case []string:
			vals = t
		case string:
			val = t
		default:
			panic(fmt.Sprintf("unsupported variable type for %s: %T", midStr, a))
		}

		// Apply variable indexing (e.g. uname.1)
		if midIdx != "" {
			if i, e := strconv.Atoi(midIdx); e == nil && 0 <= i && i < len(vals) {
				val = vals[i]
			}
		} else if val == "" && len(vals) > 0 {
			val = strings.Join(vals, " ")
		}

		// 1. Apply Chained Prefix Modifiers
		if preChain != "" {
			// FindAllString safely handles chains like "trim(+)+dir" without splitting inner args
			prefixes := rxPrefixMod.FindAllString(preChain, -1)
			
			for _, pre := range prefixes {
				act := pre
				n := 1 // Default index
				
				// Extract index if present (e.g., dir.2)
				if dotIdx := strings.LastIndex(act, "."); dotIdx != -1 {
					if i, e := strconv.Atoi(act[dotIdx+1:]); e == nil && i > 0 {
						n = i
						act = act[:dotIdx]
					}
				}

				// Extract argument if present (e.g., trim(/))
				var arg string
				if parenIdx := strings.Index(act, "("); parenIdx != -1 && strings.HasSuffix(act, ")") {
					arg = act[parenIdx+1 : len(act)-1]
					act = act[:parenIdx]
					
					// Recursively fix nested checkpoints within the argument
					if rxCheckReplacements.MatchString(arg) {
						arg = fixCheckpoint(arg)
					}
				}

				switch act {
				case "tolower":
					val = strings.ToLower(val)
				case "toupper":
					val = strings.ToUpper(val)
				case "dir":
					val = dirs(n, val)
				case "base":
					val = bases(n, val)
				case "trim":
					val = strings.TrimPrefix(val, arg)
				case "sep":
					vals = strings.Split(val, arg)
				default:
					panic(fmt.Sprintf("unknown prefix modifier %q", act))
				}
			}
		}

		// 2. Apply Suffix Modifier (if any)
		if sufAct != "" {
			if rxCheckReplacements.MatchString(sufArg) {
				sufArg = fixCheckpoint(sufArg)
			}

			switch {
			case strings.HasPrefix(sufAct, "trim("):
				val = strings.TrimSuffix(val, sufArg)

			case strings.HasPrefix(sufAct, "join("):
				val = strings.Join(vals, sufArg)

			case strings.HasPrefix(sufAct, "len("):
				if sufArg == "" {
					val = strconv.Itoa(len(val)) 
				} else {
					var num int
					if sufAdd != "" {
						fmt.Sscanf(sufAdd, "%d", &num)
					}
					val = strconv.Itoa(strings.Count(val, sufArg) + 1 + num)
				}
			
			case strings.HasPrefix(sufAct, "each("):
				var b strings.Builder
				if len(vals) == 0 && val != "" {
					vals = strings.Fields(val)
				}
				for i, s := range vals {
					if i > 0 { b.WriteString(" ") }
					fmt.Fprintf(&b, sufArg, s)
				}
				return b.String()
			
			case strings.HasPrefix(sufAct, ".("):
				var b strings.Builder
				for i, s := range strings.Split(val, ".") {
					if i > 0 { b.WriteString(" ") }
					fmt.Fprintf(&b, sufArg, s)
				}
				return b.String()
			
			case strings.HasPrefix(sufAct, "/("):
				var b strings.Builder
				for i, s := range strings.Split(val, pathSep) {
					if i == 0 && s == "" { // Handle root slash
						fmt.Fprintf(&b, sufArg, "punct", "PROOT", s)
					} else {
						vocabM.RLock()
						_, ok := symbols[s]
						vocabM.RUnlock()

						if i > 0 { b.WriteString(" ") }
						fmt.Fprintf(&b, sufArg, _if(ok,"word","raw"), s, s)
					}
				}
				return b.String()
			
			default:
				panic(fmt.Sprintf("unknown suffix modifier %q on variable %q", sufAct, midStr))
			}
		}

		return val
	})
}

type checkresult struct{ v, t any }

func fixCheckpoints1(m map[string]any) map[string]any {
	var fix func(any) any
	
	// Recursive helper to safely fix all nested checkpoint structures
	fix = func(val any) any {
		if val == nil {
			return nil
		}
		switch v := val.(type) {
		case map[string]any:
			return fixCheckpoints1(v)
		case map[string]string:
			fixedMap := make(map[string]string, len(v))
			for k, s := range v {
				fixedMap[fixCheckpoint(k)] = fixCheckpoint(s)
			}
			return fixedMap
		case string:
			return fixCheckpoint(v)
		case []string:
			fixedSlice := make([]string, len(v))
			for i, s := range v {
				fixedSlice[i] = fixCheckpoint(s)
			}
			return fixedSlice
		case sorted_list: // CRITICAL: Ensure sorted lists are also normalized!
			fixedSlice := make(sorted_list, len(v))
			for i, s := range v {
				fixedSlice[i] = fixCheckpoint(s)
			}
			return fixedSlice
		case []any:
			fixedSlice := make([]any, len(v))
			for i, a := range v {
				fixedSlice[i] = fix(a) // Recurse into nested items
			}
			return fixedSlice
		case checkresult:
			v.v = fix(v.v)
			v.t = fix(v.t)
			return v
		default:
			return v
		}
	}

	// Create a new map to avoid mutating keys during iteration
	fixedM := make(map[string]any, len(m))
	for k, v := range m {
		fixedM[fixCheckpoint(k)] = fix(v)
	}
	return fixedM
}

func fixCheckpoints(mm map[string]map[string]any) map[string]map[string]any {
	for spec, m := range mm { mm[spec] = fixCheckpoints1(m) }
	return mm
}

