func check(ctx Context, res Value, p Value, x ...Value) {
	var canIgnoreByAsteriskNil, canIgnoreByDelegateNil, canIgnoreByClosureNil bool
	switch t := unloc(p).(type) {
	case *delegate: if rxIgnoredChecks.MatchString(t.x.String()) { return }; canIgnoreByDelegateNil = true
	case *closure:  if rxIgnoredChecks.MatchString(t.x.String()) { return }; canIgnoreByClosureNil = true
	default: canIgnoreByAsteriskNil = true
	}

	var spec string
	if j := _project(ctx); j != nil { spec = j.spec.String() }
	for strings.HasPrefix(spec, "../") { spec = strings.TrimPrefix(spec, "../") }
	if !strings.HasPrefix(spec, "testdata/") { return }

	source := try[string](ctx, source{})

	// compare now returns (matched bool, debugArgs []any)
	// It NEVER calls debug() itself, leaving that decision to the caller.
	var compare func(string, any, string, bool) (bool, []*diag_point)
	compare = func(k string, expected any, actual string, is_ts bool) (bool, []*diag_point) {
		// 1. Handle Missing Checkpoints
		if expected == nil {
			if is_ts { return true, nil }

			if previous_spec != spec {
				if previous_spec != "" { prompt(ctx, "\t},//%s\n", spec) }
				previous_spec = spec
				prompt(ctx, "\t`%s`: map[string]any{\n", spec)
			}
			prompt(ctx, "\t\t`%v`:`%v`,\n", unfix(k), unfix(actual))
			flush(ctx)
			return false, nil
		}

		// 2. Handle Complex Checkpoint Types
		switch t := expected.(type) {
		case checkresult:
			var dps []*diag_point

			switch tv := t.v.(type) {
			case []string:
				var resS = res.String()
				for _, s := range tv {
					if resS == s {
						if t.t == nil { return true, nil } else { dps = nil; goto ts_check }
					}
					dps = append(dps, _f("!= : %v", s))
				}
				return false, dps
			case string:
				if res.String() == tv {
					if t.t == nil { return true, nil } else { dps = nil; goto ts_check }
				}
			}
			dps = append(dps, _f("!= : %v", t.v))
			return false, dps

		ts_check:
			var resT = ts(res, ctx)
			switch tt := t.t.(type) {
			case []string:
				for _, s := range tt {
					if resT == s { return true, nil }
					dps = append(dps, _f("!= : %v → %s", res, s))
				}
				dps = append([]*diag_point{_f("got: %v → %s", res, resT)}, dps...)
				return false, dps
			case string:
				if ts(res, ctx) == tt { return true, nil }
			}
			dps = append(dps,
				_f("got: %v → %v", res, resT),
				_f("!= : %v → %v", res, t.t),
			)
			return false, dps

		case sorted_list:
			if l, ok := res.(*list); ok {
				sort.Slice(l.elems, func(i, j int) bool {
					return l.elems[i].String() < l.elems[j].String()
				})
				if is_ts { actual = ts(res, ctx) } else { actual = res.String() }
			}
			expected = []string(t)
		}

		// 3. Handle Standard String / Multi-String Comparisons
		var dps []*diag_point
		switch t := expected.(type) {
		case []string:
			for _, s := range t {
				if s == actual { return true, nil } // Passed!
				dps = append(dps, _f("!= : %s", s))
			}
			return false, dps
		case string:
			if t == actual { return true, nil } // Passed!
		}
		dps = append(dps, _f("!= : %v", expected))
		return false, dps
	}

	// Dispatcher safely extracts keys and handles []any configurations
	do_check := func(checkpoints map[string]map[string]any, k string, is_ts bool) {
		specMap, exists := checkpoints[spec]
		if !exists && is_ts { return }

		var expected any
		if exists { expected, exists = specMap[k] }

		var canIgnoreIdentical bool // a chance to ignore ...
		if exists { 
			if canIgnoreByAsteriskNil {
				if v, ok := specMap["*"]; ok {
					if v == "*" { canIgnoreIdentical = true } // by: `xxx`:`xxx`,
				}
			}
			if canIgnoreByDelegateNil {
				if v, ok := specMap["$(*)"]; ok {
					if v == "$(*)" { canIgnoreIdentical = true } // by: `$(xxx)`:`$(xxx)`,
				}
			}
			if canIgnoreByClosureNil {
				if v, ok := specMap["&(*)"]; ok {
					if v == "&(*)" { canIgnoreIdentical = true } // by: `&(xxx)`:`&(xxx)`,
				}
			}
		} else {
			if canIgnoreByAsteriskNil {
				if v, ok := specMap["*"]; ok {
					if v == nil { return } // by: `*`:nil,
					if v == "*" { canIgnoreIdentical = true } // by: `xxx`:`xxx`,
				}
			}
			if canIgnoreByDelegateNil {
				if v, ok := specMap["$(*)"]; ok {
					if v == nil { return } // by: `$(*)`:nil,
					if v == "$(*)" { canIgnoreIdentical = true } // by: `$(xxx)`:`$(xxx)`,
				}
			}
			if canIgnoreByClosureNil {
				if v, ok := specMap["&(*)"]; ok {
					if v == nil { return } // by: `&(*)`:nil,
					if v == "&(*)" { canIgnoreIdentical = true } // by: `&(xxx)`:`&(xxx)`,
				}
			}
		}
		if canIgnoreIdentical {
			if is_ts {
				if k == ts(res,ctx) { return }
			} else {
				if k == res.String() { return }
			}
			if false { debug(ctx, "%v %v %s", p, res, ts(res,ctx)) }
		}

		var actual string
		if is_ts { actual = ts(res, ctx) } else { actual = res.String() }

		var dps []*diag_point
		switch t := expected.(type) {
		case []any:
			for _, a := range t {
				matched, d := compare(k, a, actual, is_ts)
				if matched { return } // Passed! Instantly exit the OR block.
				dps = append(dps, d...)
			}
		case map[string]any:
			if tss, ok := t[actual]; !ok {
				dps = append(dps, _f("%v: <no-expected-ts>", res))
			} else if false {
				matched, d := compare(k, tss, ts(res, ctx), true)
				if matched { return } // Passed!
				dps = append(dps, d...)
			} else {
				resT := ts(res, ctx)
				switch t := tss.(type) {
				case []string:
					for _, s := range t {
						if s == resT { return } // Passed!
						dps = append(dps, _f("!= : %v → %s", res, s))
					}
					dps = append([]*diag_point{_f("got: %v → %v", res, resT)}, dps...)
					goto done_dps
				case string:
					if t == resT { return } // Passed!
				}
				dps = append(dps,
					_f("got: %v → %v", res, resT),
					_f("!= : %v → %v", res, tss),
				)
			done_dps:
			}
		case map[string]string:
			if s, ok := t[actual]; !ok {
				dps = append(dps, _f("%v: <no-expected-ts>", res))
			} else if resT := ts(res, ctx); s != resT {
				dps = append(dps,
					_f("got: %v → %v", res, resT),
					_f("!= : %v → %v", res, s),
				)
			} else {
				return // Passed!
			}
		default:
			matched, d := compare(k, expected, actual, is_ts)
			if matched { return } // Passed!
			dps = append(dps, d...)
		}

		// If we reach here, it means NO matches were found. Dump the traces!
		debug(pc(pc(ctx, res), p),
			_f("`%v`:checkresult{`%v`,`%v`},", unfix(k), unfix(res.String()), unfix(ts(res, ctx))),
			_f("p=%s", _if(is_ts, k, ts(p, ctx))),
			_f("got: %s", _if(is_ts, ts(res, ctx), res.String())), dps,
			_f(`note: %v "%s"`, source, spec),
			callstack{stop:"smart.runcase"}, trace{})
	}

	// Execute VS Check (Value Strings)
	do_check(checkpoints_vs, p.String(), false)

	// Execute TS Check (Type/AST Strings)
	do_check(checkpoints_ts, ts(p, ctx), true)
}

var checkpoints_str = map[string]map[string]any{}
func check_string(ctx Context, v any) func(*Value, *string) {
	k := sf("%v", v)
	d, _ := do(ctx, origin_def{}).(*def)
	return func(_val *Value, _res *string) {
		p := _project(ctx);  if p == nil { return }
		t := checkpoints_str[p.spec.String()][k];  if t == nil { return }
		s := sf("%v %v", ts(*_val,ctx), *_res);  if s == t { return }
		debug(pc(ctx,d),
			_f("`%v`", k),
			_f(`got: %v`, s),
			_f(`!= : %v`, t),
			_f(`val: %v`, *_val),
			_f(`res: %v`, *_res),
			callstack{num:10}, trace{})
	}
}

