var checked_cmp = make(map[string]struct{}, len(checkpoints_cmp))
func check_cmp(ctx Context, l, r Value) func(*cmpres) {
	var k = sf("%v %v", l, r)
	if _, ok := checked_cmp[k]; ok || !truly(ctx, is_test_mode{}) {
		return func(*cmpres) {}
	}
	return func(_res *cmpres) { checked_cmp[k] = struct{}{}
		if *_res == cmpEqual {
			if rxLC.ReplaceAllString(ts(l,ctx), "{=") == rxLC.ReplaceAllString(ts(r,ctx), "{=") { return }
		}

		t := rxLC.ReplaceAllString(sf("%v", *_res), "{=")

		if v := checkpoints_cmp[k]; v == nil {
			if d, ok := l.(*def); ok && strings.Contains(d.name.String(), "use.") { return }
			if d, ok := r.(*def); ok && strings.Contains(d.name.String(), "use.") { return }
			if d, ok := l.(*delegate); ok {
				if d, ok := unbox(d.x).(*def); ok && strings.Contains(d.name.String(), "use.") { return }
				return
			}
			if d, ok := r.(*delegate); ok {
				if d, ok := unbox(d.x).(*def); ok && strings.Contains(d.name.String(), "use.") { return }
				return
			}

			if has_new_cmp_symbol>0 {/* DOES NOTHING */} else
			if _, ok := checkpoints_cmp_symbol[k]; ok {/* DOES NOTHING */} else
			if true { prompt(ctx, "	`%v`:`%v`, //cmp\n", k, t); flush(ctx) } else
			if false { prompt(ctx, "	`%v`:`%v`, //cmp: %v %v\n", k, t, l, r); flush(ctx) } else
			{ debug(pc(pc(ctx,r),l),
				_f("`%v`:`%v`,", k, t),
				_f("cmp: %v, %v", l, r),
				_f("%s, %v", ts(l,ctx), l),
				_f("%s, %v", ts(r,ctx), r),
				callstack{stop:"smart.runcase"}, trace{}) }
		} else if v != t {
			if false { prompt(ctx, "	`%v`:`%v`, // %v %v\n", k, t, l, r); flush(ctx) } else
			{ debug(pc(pc(ctx,r),l),
				_f("`%s`", k),
				_f("got: %v", t),
				_f("!= : %v", v),
				_f("cmp: %v, %v", l, r),
				_f("l: %s → %v, %v", ts(l,ctx), __symbol(ctx,l), symbolize(l)),
				_f("r: %s → %v, %v", ts(r,ctx), __symbol(ctx,l), symbolize(r)),
				callstack{stop:"smart.runcase"}, trace{}) }
		}
	}
}

var checkpoints_com = map[string]map[string]any{
	".": map[string]any{
		"[] [{1:2:word test} {1:6:punct .} {1:7:word paniconexit0}]": "[test.paniconexit0] [{=qualword {1:2:word test} {1:7:word paniconexit0}}]",
		"[] [{1:21:word test} {1:25:punct .} {1:26:word timeout}]": "[test.timeout] [{=qualword {1:21:word test} {1:26:word timeout}}]",
	},
	"value": map[string]any{
		"[] [{13:11:word x} {13:13:word y}]": "[xy] [{=compound {13:11:word x} {13:13:word y}}]",
	},
}
func check_com(ctx *comctx, a, elems []Value, res *[]Value) {
	var (
		f = dirs(1, bases(2, _position(ctx).Filename))
		k = sf("%v %v", ts(a, ctx), ts(elems, ctx))
		r = sf("%v %v", *res, ts(*res, ctx))
		t = checkpoints_com[f][k]
	)
	switch v := t.(type) {
	case   string: if r == v { return }
	case []string: for _, v := range v { if r == v { return } }
	default: if false { note(pc(ctx,elems), "%s: %v, %v => %v", f, k, t, r) }
	}
	if false { erro(pc(ctx,a), `"%v %v":"%v %v",`, a, elems, *res) }
}

