func check_matchGlobPath(ctx Context, elems, segments []Value, trail bool) func(*bool, *[]Value, *[]Value, *[]Value, *int, *int, *token) {
	var ss string
	if len(segments) == 1 {
		if p, ok := unloc(segments[0]).(*punct); ok {
			switch p.token {
			case PROOT: ss = "[ROOT]"
			case PTAIL: ss = "[TAIL]"
			}
		}
	}
	if ss == "" { ss = sf("%v", segments) }

	var k = sf("%v %v %v", elems, ss, trail)
	var v = checkpoints_matchGlobPath[k]
	return func(matched *bool, res, rem, stems *[]Value, iE, iV *int, wildToken *token) {
		if i := *iE; i < 0 { erro(ctx, "wrong iE: %v ; %v", i, k) }
		if i := *iV; i < 0 { erro(ctx, "wrong iV: %v ; %v", i, k) }
		if t := sf("%v %v %v %v %v %v %v", *matched, *res, *rem, *stems, *iE, *iV, *wildToken); v == nil {
			if p := _project(ctx); p != nil { switch spec := p.spec.String(); {
			case strings.HasSuffix(spec, ".smart/modules/lib/c++"): return
			case strings.HasSuffix(spec, ".smart/modules/lib/c++abi"): return
			case strings.HasSuffix(spec, ".smart/modules/lib/c++inc"):
				if !*matched && *res == nil && sf("%v", *rem) == "[CMakeLists.txt]" { return }
				if true { return }
			}}

			if false { prompt(ctx, `	"%s":"%s", //matchGlobPath`+"\n", k, t) } else
			{ debug(pc(ctx,elems),
				_f(`matchGlobPath: "%s":"%s",`, k, t),
				_f("elems: %v", ts(elems, ctx)),
				_f("segments: %v", ts(segments, ctx)),
				callstack{num:10}, trace{}) }	
		} else if v != t {
			if false { prompt(ctx, `	"%s":"%s", //matchGlobPath != %v`+"\n", k, t, v) } else
			{ debug(pc(ctx,elems),
				_f(`matchGlobPath: "%s": "%s" != "%s"`, k, t, v),
				_f("elems: %v", ts(elems, ctx)),
				_f("segments: %v", ts(segments, ctx)),
				callstack{num:10}, trace{}) }
		}
	}
}

