func (ctx *__foreach) check__foreach(values, vals []Value) {
	var s string
	var d, _ = do(ctx, evoke_def{}).(*def)
	switch fmt.Sprintf("%v", ctx.a[1:]) {
	case "[x$_]":
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }
			s += "x"
			if d == nil {
				s += v.String()
			} else {
				switch d.name.String() {
				case ".test.1", ".test.21", ".test.22":
					s += v.String()
				case ".test.2", ".test.23":
					s += redis(v).String()
				default:
					erro(pc(ctx,d.value), "%v %v ; %v", values, vals, d)
				}
			}
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(pc(ctx,vals), "%s != %s ; %v", s, t, d)
		}
	case "[&(.test.h)$_]":
		if d, _ := do(ctx, evoke_def{}).(*def); d == nil {
			erro(pc(ctx,vals[0]), "%v %v", values, vals)
		} else {
			switch args := fmt.Sprintf("%v", values); d.name.String() {
			case ".test.1", ".test.2":
				switch args {
				case "[a b c]":
					if truly(ctx, ex_closure{}) {
						s = "[-a -b -c]"
					} else {
						s = "[&(.test.h)a &(.test.h)b &(.test.h)c]"
					}
				default:
					erro(pc(ctx,vals[0]), "%s: %v %v", d.name, args, vals)
				}
			default:
				erro(pc(ctx,vals[0]), "%s: %v %v", d.name, args, vals)
			}
			if t := fmt.Sprintf("%v", vals); s != t {
				erro(pc(ctx,vals[0]), "%s: %s != %s", d.name, s, t)
			}
		}
	case "[&(.test.xx)$_]":
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }
			if !truly(ctx, ex_closure{}) {
				s += "&(.test.xx)"
			}
			if d == nil {
				s += v.String()
			} else {
				switch d.name.String() {
				case ".test.23":
					s += redis(v).String()
				default:
					erro(pc(ctx,d.value), "%v %v ; %v", values, vals, d)
				}
			}
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(ctx, "%s != %s", s, t)
		}
	case "[&(.test.$_.$(or $4,$3))]":
		j := _project(ctx)
		v3 := auto_get(ctx, intern("3"))
		v4 := auto_get(ctx, intern("4"))
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }

			t := ".test."+v.String()
			if v4 != nil {
				t += v4.String()
			} else if v3 != nil {
				t += v3.String()
			}

			if d := j.resolveDef(ctx, intern(t)); d == nil {
				erro(ctx, "%v", t)
			} else if truly(ctx, ex_closure{}) {
				s += ""
			} else /* if truly(ctx, ex_delegate{}) */ {
				s += "{&(.test.xx)}"
			}
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(ctx, "%s != %s", s, t)
		}
	case "[$(closure .test.$_)$1{}99]":
		j := _project(ctx)
		v1 := auto_get(ctx, intern("1"))
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }

			t := ".test."+v.String()
			if d := j.resolveDef(ctx, intern(t)); d == nil {
				erro(ctx, "%v", t)
			} else if truly(ctx, ex_closure{}) {
				s += ""
			} else /* if truly(ctx, ex_delegate{}) */ {
				s += "{&(.test.xx)}"
			}
			s += v1.String()
			s += "99"
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(ctx, "%s != %s", s, t)
		}
	case "[&(.test.x $_)]":
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }
			if truly(ctx, ex_closure{}) {
				s += ""
			} else /* if truly(ctx, ex_delegate{}) */ {
				s += "{&(.test.xx)}"
				s += v.String()
			}
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(ctx, "%s != %s", s, t)
		}
	case "[&(.test.$_)$1{}zz]":
		s += "["
		for i, v := range values {
			if i > 0 { s += " " }
			if truly(ctx, ex_closure{}) {
				s += ""
			} else /* if truly(ctx, ex_delegate{}) */ {
				s += "{&(.test.xx)}"
				s += v.String()
			}
		}
		s += "]"
		if t := fmt.Sprintf("%v", vals); s != t {
			erro(ctx, "%s != %s", s, t)
		}
	default:
		erro(ctx, "%d %v %v %v", len(values), values, vals, ctx.a)
	}
}

