func (prog *program) execute_check(ctx *execution, result *Value) {
	switch prog.project.name {
	case intern("configure.base"):
		if x1, y := ctx.defs[intern("TYPE")]; y {
			if x2, y := ctx.defs[intern("TARGET")]; y {
				s := strings.ToUpper(__string(ctx, x1))
				s  = strings.Replace(s, " ", "_",  -1)
				s  = strings.Replace(s, "*", "_P", -1)
				if t := __string(ctx, x2); "SIZEOF_"+s != t && "ALIGNOF_"+s != t {
					debug(ctx, "%v : %s != %s", ctx.prerequisite, s, t)
				}
				if a, y := ctx.prerequisite.(*argumented); false && y && a != nil {
					note(ctx, "%v %v %v", a, x1, x2)
				}
			}
		}
	case intern("testdefaultconfigure"):
		ent := _entry(ctx)
		if t := ent.destiny(); t == nil {
			debug(ctx, "%v", ent)
		} else {
			switch t.String() {
			case "FOO":
				var v = *result
				if v == nil {
					debug(ctx, "%v", t)
				} else if d, y := v.(*def); !y {
					debug(ctx, "%v", t)
				} else if v = d.value; v == nil {
					debug(ctx, "%v", d)
				} else if v.String() != "{=self testdefaultconfigure}" {
					debug(ctx, "%v", d)
				}
				if d := prog.project.finddef(intern("FOO")); d == nil {
					debug(ctx, "%v", t)
				} else if d.value == nil {
					debug(ctx, "%v ; %v", d, v)
				} else if d.value != v {
					debug(ctx, "%v", d)
				}
			}
		}
	}
	switch prog.project.spec {
	case intern("testdata/rule/0"): prog.execute_check_rule_0(ctx, result)
	case intern("testdata/rule/1"): prog.execute_check_rule_1(ctx, result)
	case intern("testdata/rule/shell/for-stdout"):
		prog.execute_check_shell_for_stdout(ctx, result)
	}
}

func (prog *program) execute_check_0(ctx *execution) {
	switch prog.project.name {
	case intern("configure.base"):
		switch t := prog.target(ctx); t.String() {
		case "-sizeof-c":
			for _, dep := range prog.depends {
				if x, y := dep.(*argumented); y && x.Value.String() == "$(name).c.x" {
					if len(x.args) != 3 {
						debug(ctx, "%v %v", t, x)
					}
					for i, s := range []string{"$(TYPE)","$(INCLUDE)","$(LIB)"} {
						if x.args[i].String() != s {
							debug(ctx, "%v %v %v != %s", t, x.Value, x.args[i], s)
						}
					}
				}
			}
		default:
			if false { debug(ctx, "%v", t) }
		}
	}
}

func (prog *program) execute_check_1(ctx *execution) {
	switch prog.project.name {
	case intern("configure.base"):
		if t := _entry(ctx).destiny(); t == nil {
			debug(ctx, "%v: %v", _entry(ctx))
		} else if false {
			var s = _scope(ctx)
			switch t.String() {
			case "-compiles-c":
				if d := s.finddef(intern("name")); d == nil {
					debug(ctx, "%v : name", t)
				} else if d.value.String() != ".configure/compiles/$(TARGET)" {
					debug(ctx, "%v : %s", t, d.value)
				}
			case "-library-c":
				if d := s.finddef(intern("name")); d == nil {
					debug(ctx, "%v : name", t)
				} else if d.value.String() != ".configure/library/$(TARGET)" {
					debug(ctx, "%v : %s", t, d.value)
				}
				if d := s.finddef(intern("s")); d == nil {
					debug(ctx, "%v : name", t)
				} else if d.value.String() != "$(file .configure/$(ifdef $(FUNCTION),function,library)/$(TARGET).c)" {
					debug(ctx, "%v : %s", t, d.value)
				}
				if d := s.finddef(intern("x")); d == nil {
					debug(ctx, "%v : name", t)
				} else if d.value.String() != "$(file $(s).x)" {
					debug(ctx, "%v : %s", t, d.value)
				}
				if d := s.finddef(intern("o")); d == nil {
					debug(ctx, "%v : name", t)
				} else if d.value.String() != "$(file $(s).o)" {
					debug(ctx, "%v : %s", t, d.value)
				}
			}
		}
	}
}

func (prog *program) execute_check_rule_0(ctx Context, result *Value) {
	var ent = _entry(ctx)
    if *result == nil {
        debug(ctx, "%v: nil result", ts(ent,ctx))
    }

    var args = try[[]Value](ctx, get_args{})

    switch __string(ctx, ent.destiny()) {
    case "rule0":
        if len(args) != 3 {
            debug(ctx, "%v: %d %v", ent, len(args), ts(args))
        }
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{9:1:word rule0}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{9:24:word rule1}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{9:24:word rule1}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("^")); ts(v,ctx) != "{=list {9:24:word rule1}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if v := auto_get(ctx, intern("-")); ts(v,ctx) != "{=list {10:2 {9:24:word rule1}} {10:5 {9:24:word rule1}} {=flag {10:9}} {=compound {10:10 {1:9:word x}} {10:17 {1:9:word y}} {10:24 {1:9:word z}}}}" {
			debug(ctx, "%v", ts(v,ctx))
		}
		if auto_get(ctx, intern("<")) != auto_get(ctx, intern(">")) {
			debug(ctx, "%v %v", ts(auto_get(ctx, intern("<"))), ts(auto_get(ctx, intern(">"))))
		}
        if x, y := (*result).(*list); !y {
            debug(ctx, "%v: %v", ent, ts(*result,ctx))
        } else if x.len() != 4 {
            debug(ctx, "%v: %v", ent, ts(*result,ctx))
        } else if s := ts(x.elems[0],ctx); s != "{10:2 {9:24:word rule1}}" {
            debug(ctx, "%v: %v", ent, s)
        } else if s := ts(x.elems[1],ctx); s != "{10:5 {9:24:word rule1}}" {
            debug(ctx, "%v: %v", ent, s)
        } else if s := ts(x.elems[2],ctx); s != "{=flag {10:9}}" {
            debug(ctx, "%v: %v", ent, s)
        } else if s := ts(x.elems[3],ctx); s != "{=compound {10:10 {1:9:word x}} {10:17 {1:9:word y}} {10:24 {1:9:word z}}}" {
            debug(ctx, "%v: %v", ent, s)
        }
        if ts(*result,ctx) != "{=list {10:2 {9:24:word rule1}} {10:5 {9:24:word rule1}} {=flag {10:9}} {=compound {10:10 {1:9:word x}} {10:17 {1:9:word y}} {10:24 {1:9:word z}}}}" {
            debug(ctx, "%v: %v, %v", ent, ts(*result,ctx), args)
        }
    case "rule1":
		if len(args) != 1 {
			debug(ctx, "%v: %d %v", ent, len(args), ts(args))
		}
		if v := auto_get(ctx, intern("@")); ts(v,ctx) != "{12:1:word rule1}" {
			debug(ctx, "%v: %v", v, ts(v,ctx))
		}
		if v := auto_get(ctx, intern("<")); ts(v,ctx) != "{}" {
			debug(ctx, "%v: %v", v, ts(v,ctx))
		}
		if v := auto_get(ctx, intern(">")); ts(v,ctx) != "{}" {
			debug(ctx, "%v: %v", v, ts(v,ctx))
		}
		if v := auto_get(ctx, intern("^")); ts(v,ctx) != "{}" {
			debug(ctx, "%v: %v", v, ts(v,ctx))
		}
		if v := auto_get(ctx, intern("ARG1")); v == nil {
			debug(ctx, "ARG1")
		} else if s := ts(v,ctx); s == "" {
			debug(ctx, "%v", v)
		} else if t := "{1:9:word xxYzz}"; s == t {
			if v := auto_get(ctx, intern("-")); v == nil {
				debug(ctx, "-")
			} else if s, t := ts(v,ctx), "{=plain(text) {=plainline {13:2 {1:9:word xxYzz}}}}"; s != t {
				debug(ctx, "%s != %s", s, t)
			}
			if x, y := (*result).(*plain); !y {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.name != intern("text") {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.len() != 1 {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if s := ts(x.elems[0],ctx); s != "{=plainline {13:2 {1:9:word xxYzz}}}" {
				debug(ctx, "%v: %v", ent, s)
			}
			if s, t := __string(ctx, *result), "xxYzz\n"; s != t {
				debug(ctx, "%v: %v: %s != %s", ent, ts((*result),ctx), s, t)
			}
		} else if t := "{=list {9:30 {9:1:word rule0}} {9:33:word xyz}}"; s == t {
			if v := auto_get(ctx, intern("-")); v == nil {
				debug(ctx, "-")
			} else if s, t := ts(v,ctx), "{=plain(text) {=plainline {=list {13:2 {9:30 {9:1:word rule0}}} {13:2 {9:33:word xyz}}}}}"; s != t {
				debug(ctx, "%s != %s", s, t)
			}
			if x, y := (*result).(*plain); !y {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.name != intern("text") {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.len() != 1 {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x, y := x.elems[0].(*plainline); !y {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.len() != 1 {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x, y := x.elems[0].(*list); !y {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if x.len() != 2 {
				debug(ctx, "%v: %v", ent, ts(*result,ctx))
			} else if s := ts(x.elems[0],ctx); s != "{13:2 {9:30 {9:1:word rule0}}}" {
				debug(ctx, "%v: %v", ent, s)
			} else if s := ts(x.elems[1],ctx); s != "{13:2 {9:33:word xyz}}" {
				debug(ctx, "%v: %v", ent, s)
			}
			if s, t := __string(ctx, *result), "rule0 xyz\n"; s != t {
				debug(ctx, "%v: %v: %s != %s", ent, ts((*result),ctx), s, t)
			}
		} else {
			debug(ctx, "%v : %s != %s ; %s", v, s, t, __string(ctx, v))
		}
    }
}

